import java.util.List;
import java.util.function.Function;

public class MethodReferenceDemo {
    public static void main(String[] args) {
        var names = List.of("alice", "bob", "charlie");

        // Lambda approach - explicit parameter and method call
        names.stream()
             .map(name -> name.toUpperCase())
             .forEach(result -> System.out.println(result));

        // Method reference approach - cleaner and more concise
        names.stream()
             .map(String::toUpperCase)  // unbound instance method reference
             .forEach(System.out::println);  // bound instance method reference

        // Both produce identical results and bytecode
        Function<String, Integer> lambdaVersion = s -> s.length();
        Function<String, Integer> methodRefVersion = String::length;

        System.out.println(lambdaVersion.apply("test"));  // 4
        System.out.println(methodRefVersion.apply("test"));  // 4
    }
}

