import java.util.List;

public class MethodRefVsLambda {
    public static void main(String[] args) {
        var names = List.of("amy", "bob");

        // pure forwarding -> method reference
        names.forEach(System.out::println);
        names.stream().map(String::toUpperCase).toList();

        // adds real logic -> keep the lambda
        names.stream().map(s -> s.toUpperCase() + "!").toList();
        names.forEach(s -> System.out.println("Name: " + s));
    }
}
